#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int m, n;
    scanf("%d %d", &m, &n);
    int *counts = malloc((size_t)m * sizeof *counts);
    if (counts == NULL) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        counts[x]++;
    }
    for (int v = 0; v < m; v++) {
        if (counts[v] > 0) {
            printf("%d: %d\n", v, counts[v]);
        }
    }
    free(counts);
    return 0;
}

