#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *copy_word(const char *word) {
    size_t len = strlen(word);
    char *copy = malloc(len + 1);
    if (copy == NULL) {
        return NULL;
    }
    memcpy(copy, word, len);
    return copy;
}

int main(void) {
    char buffer[64];
    while (scanf("%63s", buffer) == 1) {
        char *copy = copy_word(buffer);
        if (copy == NULL) {
            return 1;
        }
        printf("%s %zu\n", copy, strlen(copy));
        free(copy);
    }
    return 0;
}

