#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

int main(void) {
    struct Node *head = NULL;
    int x;
    while (scanf("%d", &x) == 1) {
        struct Node *node = malloc(sizeof *node);
        if (node == NULL) {
            break;
        }
        node->value = x;
        node->next = head;
        head = node;
    }
    long long sum = 0;
    int count = 0;
    for (struct Node *n = head; n != NULL; n = n->next) {
        sum += n->value;
        count++;
    }
    printf("count=%d sum=%lld\n", count, sum);
    free(head);
    return 0;
}

