#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *reversed(const char *s) {
    size_t len = strlen(s);
    char *out = malloc(len);
    if (out == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < len; i++) {
        out[i] = s[len - 1 - i];
    }
    out[len] = '\0';
    return out;
}

int main(void) {
    char buffer[64];
    while (scanf("%63s", buffer) == 1) {
        char *r = reversed(buffer);
        if (r == NULL) {
            return 1;
        }
        printf("%s\n", r);
        free(r);
    }
    return 0;
}

